const stone = find_block({ names: ['stone', 'cobblestone', 'andesite', 'diorite'], max_distance: 32 });
if (!stone) {
  return { done: false, detail: 'no stone within 32 blocks' };
}
await dig(stone.x, stone.y, stone.z);
const opened = await open_chest();
if (!opened.ok) {
  return { done: false, detail: opened.detail };
}
const put = await deposit('cobblestone', 1);
if (!put.ok) {
  return { done: false, detail: put.detail };
}
return { done: true, detail: 'mined stone and put it in the chest' };
